                return;
            }
            throw new Exception("Cannot marshal type double");
        }

        public static readonly FluffyMinMaxValueCheckConverter Singleton = new FluffyMinMaxValueCheckConverter();
    }

    internal class SourceConverter : JsonConverter<Source>
    {
        public override bool CanConvert(Type t) => t == typeof(Source);

