        {
            var value = reader.GetString();
            switch (value)
            {
                case "declared":
                    return Source.Declared;
                case "default":
                    return Source.Default;
                case "inferred":
                    return Source.Inferred;
                case "model":
                    return Source.Model;
            }
            throw new Exception("Cannot unmarshal type Source");
        }

        public override void Write(Utf8JsonWriter writer, Source value, JsonSerializerOptions options)
        {
            switch (value)
            {
                case Source.Declared:
                    JsonSerializer.Serialize(writer, "declared", options);
                    return;
                case Source.Default:
                    JsonSerializer.Serialize(writer, "default", options);
                    return;
                case Source.Inferred:
                    JsonSerializer.Serialize(writer, "inferred", options);
                    return;
                case Source.Model:
                    JsonSerializer.Serialize(writer, "model", options);
                    return;
            }
            throw new Exception("Cannot marshal type Source");
        }

        public static readonly SourceConverter Singleton = new SourceConverter();
    }

